import React, { useState } from 'react';
import { Alert, SafeAreaView, ScrollView, StyleSheet, Text, TextInput, TouchableOpacity, View } from 'react-native';
import { MaterialCommunityIcons } from '@expo/vector-icons';
import { Colors, BorderRadius, Shadows, Spacing } from '@constants/colors';

interface Evacuee { id: string; name: string; age: number; center: string; status: 'Registered' | 'In transit' | 'Arrived'; }
const seed: Evacuee[] = [
  { id: 'EV-001', name: 'Ramon Garcia', age: 42, center: 'Biñan City Multi-Purpose Hall', status: 'Arrived' },
  { id: 'EV-002', name: 'Liza Garcia', age: 38, center: 'Biñan City Multi-Purpose Hall', status: 'Arrived' },
  { id: 'EV-003', name: 'Noel Bautista', age: 67, center: 'School Gymnasium', status: 'Registered' },
];

export default function AdminEvacuees() {
  const [records, setRecords] = useState(seed);
  const [query, setQuery] = useState('');
  const visible = records.filter((record) => `${record.name} ${record.center} ${record.status}`.toLowerCase().includes(query.toLowerCase()));
  const create = () => Alert.prompt('Create evacuee record', 'Enter the evacuee name', (name) => { if (name?.trim()) setRecords((current) => [...current, { id: `EV-00${current.length + 1}`, name: name.trim(), age: 0, center: 'Unassigned', status: 'Registered' }]); });
  const archive = (id: string) => Alert.alert('Archive record', 'Archive this evacuee record?', [{ text: 'Cancel', style: 'cancel' }, { text: 'Archive', style: 'destructive', onPress: () => setRecords((current) => current.filter((record) => record.id !== id)) }]);
  return <SafeAreaView style={styles.safe}><ScrollView contentContainerStyle={styles.content}><View style={styles.heading}><View><Text style={styles.eyebrow}>EVACUEE MANAGEMENT</Text><Text style={styles.title}>Evacuee directory</Text><Text style={styles.subtitle}>Create, view, edit, and archive registration records.</Text></View><TouchableOpacity style={styles.primary} onPress={create}><MaterialCommunityIcons name="account-plus-outline" size={18} color={Colors.white} /><Text style={styles.primaryText}>Create record</Text></TouchableOpacity></View><View style={styles.summary}><Text style={styles.total}>{records.length}</Text><Text style={styles.summaryLabel}>records in this view</Text></View><View style={styles.panel}><View style={styles.search}><MaterialCommunityIcons name="magnify" size={19} color={Colors.textMuted} /><TextInput value={query} onChangeText={setQuery} placeholder="Search evacuees, centers, or status" placeholderTextColor={Colors.textMuted} style={styles.input} /></View>{visible.map((record) => <View style={styles.row} key={record.id}><View style={styles.avatar}><Text style={styles.avatarText}>{record.name.split(' ').map((part) => part[0]).join('').slice(0, 2)}</Text></View><View style={styles.copy}><Text style={styles.name}>{record.name}</Text><Text style={styles.detail}>{record.id} · Age {record.age || 'not set'} · {record.center}</Text></View><Text style={[styles.status, { color: record.status === 'Arrived' ? '#167A5B' : '#8B5E00' }]}>{record.status}</Text><TouchableOpacity style={styles.action} onPress={() => Alert.alert('Edit record', `${record.name} is ready to be updated.`)}><MaterialCommunityIcons name="pencil-outline" size={19} color={Colors.secondary} /></TouchableOpacity><TouchableOpacity style={styles.action} onPress={() => archive(record.id)}><MaterialCommunityIcons name="archive-outline" size={19} color={Colors.emergency} /></TouchableOpacity></View>)}</View></ScrollView></SafeAreaView>;
}
const styles = StyleSheet.create({ safe: { flex: 1, backgroundColor: '#F4F7F9' }, content: { padding: Spacing.xl, paddingBottom: 48, maxWidth: 1100, width: '100%', alignSelf: 'center' }, heading: { flexDirection: 'row', justifyContent: 'space-between', gap: 16, marginBottom: 22 }, eyebrow: { color: Colors.secondary, fontSize: 11, fontWeight: '800', letterSpacing: 1.2 }, title: { color: Colors.text, fontSize: 30, fontWeight: '800', marginTop: 5 }, subtitle: { color: Colors.textMuted, fontSize: 14, marginTop: 6 }, primary: { flexDirection: 'row', gap: 8, alignItems: 'center', backgroundColor: Colors.primary, paddingHorizontal: 15, paddingVertical: 12, borderRadius: BorderRadius.md }, primaryText: { color: Colors.white, fontSize: 12, fontWeight: '700' }, summary: { backgroundColor: Colors.white, padding: 16, borderRadius: BorderRadius.md, marginBottom: 16, ...Shadows.sm }, total: { color: Colors.text, fontSize: 26, fontWeight: '800' }, summaryLabel: { color: Colors.textMuted, fontSize: 12 }, panel: { backgroundColor: Colors.white, padding: 18, borderRadius: BorderRadius.md, ...Shadows.sm }, search: { flexDirection: 'row', alignItems: 'center', borderWidth: 1, borderColor: '#D7E2EA', borderRadius: BorderRadius.sm, paddingHorizontal: 10, marginBottom: 8 }, input: { flex: 1, padding: 10, color: Colors.text, fontSize: 13 }, row: { flexDirection: 'row', alignItems: 'center', gap: 12, borderTopWidth: 1, borderTopColor: '#EDF1F4', paddingVertical: 14 }, avatar: { width: 38, height: 38, borderRadius: 19, backgroundColor: '#E4EEF4', alignItems: 'center', justifyContent: 'center' }, avatarText: { color: Colors.primary, fontSize: 12, fontWeight: '800' }, copy: { flex: 1 }, name: { color: Colors.text, fontSize: 13, fontWeight: '700' }, detail: { color: Colors.textMuted, fontSize: 11, marginTop: 4 }, status: { width: 75, fontSize: 11, fontWeight: '700' }, action: { padding: 7 } });